    let v: Vec<char> = normalize(s).chars().collect();
    if v.len() <= 1 { return true; }
    if v[0] != v[v.len() - 1] { return false; }
    is_palindrome_recursive(&v[1..v.len() - 1].iter().collect::<String>())
}

